import sys
from rich.console import Console
from rich.file_proxy import FileProxy

def test_file_proxy_isatty():
    # Create a mock file that has isatty returning True
    class MockFile:
        def isatty(self):
            return True
        def write(self, text):
            pass
        def flush(self):
            pass
        def fileno(self):
            return 1

    mock_file = MockFile()
    console = Console(file=mock_file)
    print(f"Console is_terminal (direct): {console.is_terminal}")

    proxy = FileProxy(console, mock_file)
    console.file = proxy
    print(f"Console is_terminal (proxied): {console.is_terminal}")

    assert console.is_terminal is True

if __name__ == "__main__":
    test_file_proxy_isatty()

